describe('Filter List by Multiple Statuses', () => {
  beforeEach(() => {
    cy.visit('/list');
  });

  it('should filter list by multiple selected statuses simultaneously', () => {
    // Intercept the API call for fetching list items
    cy.intercept('GET', '/api/list').as('getFilteredList');

    // Verify initial list is displayed
    cy.get('[data-testid="list-container"]').should('be.visible');
    cy.get('[data-testid="list-item"]').should('have.length.greaterThan', 0);

    // Select multiple status filters
    cy.get('[data-testid="status-filter-all"]').click();
    cy.get('[data-testid="status-filter-active"]').click();
    cy.get('[data-testid="status-filter-pending"]').click();

    // Verify selected filters are marked
    cy.get('[data-testid="status-filter-all"]').should('have.class', 'selected');
    cy.get('[data-testid="status-filter-active"]').should('have.class', 'selected');
    cy.get('[data-testid="status-filter-pending"]').should('have.class', 'selected');

    // Verify API call is made with multiple filters
    cy.wait('@getFilteredList');

    // Verify list is updated with filtered results
    cy.get('[data-testid="list-item"]').should('be.visible');
    cy.get('[data-testid="list-item"]').should('have.length.greaterThan', 0);

    // Verify filter applied successfully
    cy.get('[data-testid="filter-applied-message"]').should('contain', 'Showing results for Active, Pending');
  });

  it('should clear all filters when reset button is clicked', () => {
    // Intercept the API call for fetching list items
    cy.intercept('GET', '/api/list').as('getFilteredList');

    // Select multiple status filters
    cy.get('[data-testid="status-filter-active"]').click();
    cy.get('[data-testid="status-filter-pending"]').click();

    // Verify filters are applied
    cy.wait('@getFilteredList');
    cy.get('[data-testid="list-item"]').should('have.length.greaterThan', 0);

    // Click reset button
    cy.get('[data-testid="reset-filters-button"]').click();

    // Verify all filters are deselected
    cy.get('[data-testid="status-filter-active"]').should('not.have.class', 'selected');
    cy.get('[data-testid="status-filter-pending"]').should('not.have.class', 'selected');

    // Verify API call is made with no filters
    cy.intercept('GET', '/api/list').as('getUnfilteredList');
    cy.wait('@getUnfilteredList');

    // Verify list is reset to show all items
    cy.get('[data-testid="list-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="filter-applied-message"]').should('not.exist');
  });
});
